mapper.select:
SELECT COUNT(*) total_orders,
       COALESCE(SUM(EXISTS(SELECT 1 FROM trd_payment p WHERE p.order_id=o.id AND p.status='SUCCEEDED')),0) paid_orders,
       COALESCE(SUM(EXISTS(SELECT 1 FROM trd_refund r WHERE r.order_id=o.id)),0) refunded_orders,
       COALESCE(SUM(CASE WHEN o.status='COMPLETED' THEN o.total_cent ELSE 0 END),0) completed_amount_cent
FROM trd_order o WHERE o.created_at >= #{start} AND o.created_at < #{end}
AND o.merchant_id=#{merchant}

SELECT DATE_FORMAT(o.created_at,'%Y-%m-%d') day, COUNT(*) order_count FROM trd_order o
WHERE o.created_at >= #{start} AND o.created_at < #{end} AND o.merchant_id=#{merchant}
GROUP BY DATE_FORMAT(o.created_at,'%Y-%m-%d') ORDER BY day

SELECT o.status, COUNT(*) order_count, COALESCE(SUM(o.total_cent),0) amount_cent FROM trd_order o
WHERE o.created_at >= #{start} AND o.created_at < #{end} AND o.merchant_id=#{merchant}
GROUP BY o.status ORDER BY o.status

SELECT i.sku_id, MAX(i.title) title, COALESCE(SUM(i.quantity),0) quantity FROM trd_order o JOIN trd_order_item i ON i.order_id=o.id
WHERE o.status='COMPLETED' AND o.created_at >= #{start} AND o.created_at < #{end} AND o.merchant_id=#{merchant}
GROUP BY i.sku_id ORDER BY quantity DESC,i.sku_id LIMIT 20
